<?php

namespace App\Providers\Modules;

use App\Ai\Tools\ProjectsCreate;
use App\Ai\Tools\ProjectsDelete;
use App\Ai\Tools\ProjectsList;
use App\Ai\Tools\ProjectsUpdate;
use Illuminate\Support\ServiceProvider;
use Starter\Ai\Agents\ToolDefinition;
use Starter\Ai\Agents\ToolKind;
use Starter\Ai\Agents\ToolRegistry;
use Starter\Identity\Permissions;

/**
 * Module Projects (generated by starter:make-module): permission catalog
 * entries and AI tools (same Actions as the panel). Run `php artisan starter:permissions` after adding
 * or changing permissions.
 */
class ProjectsServiceProvider extends ServiceProvider
{
    public function register(): void
    {
        Permissions::register('projects', [
            'projects.read' => 'View projects',
            'projects.create' => 'Create projects',
            'projects.update' => 'Edit projects',
            'projects.delete' => 'Delete projects',
        ], [
            Permissions::EDITOR => ['projects.read', 'projects.create', 'projects.update', 'projects.delete'],
            Permissions::READER => ['projects.read'],
        ]);

        $this->callAfterResolving(ToolRegistry::class, function (ToolRegistry $registry) {
            $registry->register(new ToolDefinition('projects_list', ProjectsList::class, 'projects', 'Search projects', ToolKind::Read, 'projects.read'));
            $registry->register(new ToolDefinition('projects_create', ProjectsCreate::class, 'projects', 'Create a project', ToolKind::Write, 'projects.create'));
            $registry->register(new ToolDefinition('projects_update', ProjectsUpdate::class, 'projects', 'Update a project', ToolKind::Write, 'projects.update'));
            $registry->register(new ToolDefinition('projects_delete', ProjectsDelete::class, 'projects', 'Delete a project', ToolKind::Sensitive, 'projects.delete'));
        });
    }
}
